steps.preRequestScript:
// Data de partida calculada na hora (nunca fixa). O DevFlow resolve os {{...}} do body
// DEPOIS do pre-request, então {{flowDeparture}} já vale nesta mesma request.
var moment = require("moment");
pm.environment.set("flowDeparture", moment().add(90, "days").format("YYYY-MM-DD"));
// Começa vazio: sem voo nesta busca, o Order não usa o voo de outra execução.
pm.environment.set("journeyKeyIda", "");
pm.environment.set("fareKeyIda", "");

steps.postResponseScript:
// 1º voo da ida com tarifa; usa a 1ª tarifa dele (regra do Flow 01).
// Caminhos confirmados no run de 13/11/2026: data.airResult.offers[] → offersAvailableByMarket[] → value[] (voo: key, fares[].key).
var response = pm.response.json();
var offers = (response.data && response.data.airResult && response.data.airResult.offers) || [];
var markets = offers.length ? (offers[0].offersAvailableByMarket || []) : [];
var journey = null;
for (var m = 0; m < markets.length && !journey; m++) {
  var values = markets[m].value || [];
  for (var v = 0; v < values.length; v++) {
    if (values[v].fares && values[v].fares.length) { journey = values[v]; break; }
  }
}
if (journey) {
  pm.environment.set("journeyKeyIda", journey.key);
  pm.environment.set("fareKeyIda", journey.fares[0].key);
} else {
  console.log("Nenhum voo com tarifa nesta busca.");
}
